  for (const [at, s] of NEW_TIPS[id]) kept.splice(at, 0, s);
  const parts = (DROPPED[id] || []).map((i) => b.buying_tips[i]);
  if (NOTE_DEMOTED.includes(id)) parts.push(b.tier_note);
