  if (parts.length) e.detail = `${b.detail} ${parts.join(' ')}`;
  if (id === 'organic_worth_it_by_type') {
    e.labels_decoded = structuredClone(b.labels_decoded);
    e.labels_decoded[0].meaning = NARROWED;
