  });
  // The two-line rewrite (2026-10-17) owns decision/buying_tips now: twoLinePin.test.js.
  assert.deepEqual({ ...kb, entries: kb.entries.map((e) => beforeConcern(beforeTwoLine(e))) }, { ...before, entries: expected });
