// Kept as exports for callers/probes; the implementation now guards shared scoring.
export { STATES, statesIn, cardStates, stateContradicts } from './perimeter.js';

/**
 * The card a written grocery item resolves to, or null.
 *
 * A HOME CARD NEVER ATTACHES TO A LIST ITEM, and it falls through rather than failing.
 * `kind === 'home'` is kitchen technique: what to do with food you already own. Writing
 * "lettuce" on a list matches `revive_greens` outright — "limp is water loss, not spoilage,
 * it comes back" — which is a true and useful card and the wrong answer to a shopper
 * standing in produce deciding what to buy. It is the same category error the projection
 * already prevents one step later by suppressing add-to-cart on home cards; this is that
 * rule applied one step earlier, where the item is created.
 *
 * @returns {{ slug:string, section:string|null, score:number }|null}
 */
export function matchItemToCard(name) {
  const q = String(name || '').trim();
  if (!q) return null;

  for (const c of scoreEntries(q, CANDIDATES)) {
    if (c.score < CONFIDENT || c.aliasScore <= 0) continue;
    if (kindFor(c.entry.id) === 'home') continue;
    if (NON_AISLE_SECTIONS.has(sectionForCategory(c.entry.category))) continue;
    if (!aliasNamesHead(q, c.entry)) continue;
    return {
      slug: c.entry.id,
      section: sectionForCategory(c.entry.category),
      score: c.score,
    };
  }
  return null;
}

/**
 * THE PICK FLOOR. Scored only for a row that ended with NO card — the caller enforces that
 * order (`attachCards`), never this function. Same alias-containment scorer, same gate, same
 * `stateContradicts` veto: a stateless produce pick reads as fresh, so "Canned tomatoes"
 * cannot pick up a fresh-tomato line. No home / label check is needed — `lintPick` refuses
 * a pick filed there. `pool` is injectable because the corpus holds no picks yet.
 *
 * @returns {{ id:string, line:string }|null}
 */
export function matchItemToPick(name, pool = perimeterKb.entries || []) {
  const q = String(name || '').trim();
  if (!q) return null;
  for (const c of scorePool(q, pickEntries(pool), CANDIDATES)) {
    if (c.score < CONFIDENT || c.aliasScore <= 0) continue;
    if (!c.entry.decision) continue;
    if (!aliasCoversRow(q, c.entry)) continue;
    return { id: c.entry.id, line: c.entry.decision };
  }
  return null;
}

// One trailing plural, folded so "carrot" and "carrots" are the same word. Both sides of
// every comparison go through it, so a word it mangles ("asparagus" → "asparagu") still
// agrees with itself.
const singular = (w) => w.replace(/(?:[sxz]|[cs]h|o)es$/, (m) => m.slice(0, -2)).replace(/(?<=[^s])s$/, '');
const rowWords = (s) =>
  String(s || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').split(/\s+/)
    .filter((w) => w && !/^\d+$/.test(w)).map(singular);

/**
 * THE ROW'S HEAD NOUN, AND EVERY OTHER WORD ON IT, MUST BE IN ONE ALIAS OF THE PICK.
 *
 * Containment alone let a bare-noun alias land on any compound row that carried it: "oat
 * milk" → the milk pick, whose line says the carton may hold raw milk; "corn tortillas" →
 * corn; "garlic powder" → garlic; "carrot cake" → carrots. The head-noun check (the Swift
 * fix for the one-word over-match, applied to the floor) is not enough on its own — "oat
 * milk", "coconut milk" and "lemon juice" share their head with the alias — so the rule is
 * the whole row: a modifier the pick's aliases never name is a different food. Cards get
 * the head-noun half of this (`aliasNamesHead`, below, and why only half); this is the
 * floor only. Numbers are ignored ("2 carrots" is carrots).
 */
function aliasCoversRow(name, entry) {
  const words = contentWords(name);
  if (!words.length) return false;
  return (entry.aliases || []).some((a) => {
    const has = new Set(rowWords(a));
    return words.every((w) => has.has(w));
  });
}

// The row's words with the inert modifiers stripped — the unit both guards read.
const contentWords = (name) => rowWords(name).filter((w) => !INERT_MODIFIERS.has(w));

/**
 * THE CARD-PATH GUARD: THE ROW'S HEAD NOUN MUST BE IN ONE ALIAS OF THE CARD.
 *
 * Cards run first, so `aliasCoversRow` on the floor never saw "carrot cake" once
 * `produce_root_vegetables` carried the bare alias "carrots": the card attached and the
 * shopper was told how to pick a root vegetable for a cake. Porting the whole-row rule to
 * cards was measured and rejected — card aliases are question-shaped, and multi-word rows
 * attach on SEVERAL aliases at once ("Brown or jasmine rice", "Bone-in, skin-on chicken
 * thighs", "cheddar cheese"); requiring every word in ONE alias cost eight correct rows
 * and one of the 26. The head noun is the product (the Swift fix for the one-word
 * over-match, CLAUDE.md): "carrot cake" is a cake, "garlic powder" is a powder, "broccoli
 * slaw" is a slaw, and no produce card's aliases name any of them. A row whose head IS the
 * card's noun — "organic carrots", "whole carrots", "2 carrots" — still lands.
 *
 * It is weaker than the floor's rule on purpose and only for the rows the floor's rule
 * misfiles; a compound whose head is the card's own noun ("oat milk" against a milk card)
 * is left to the card's aliases, as it was. Numbers and inert modifiers are ignored either
 * side, so "carrots, organic" reads carrots.
 *
 * THE HEAD IS TAKEN BEFORE A TRAILING QUALIFIER. "Peanut butter — just peanuts and salt" is
 * peanut butter; the words after the dash describe the label. Read whole, its last word was
 * "salt" and the row missed a card the bare name reaches. So the head is the last word of
 * the text BEFORE the first separator (dash, colon, semicolon, open paren). A row that puts
 * its product after one ("Organic: carrots") now misses instead of matching — the cheap
 * direction — and the probe pins that no shipping row does.
 *
 * THE COMMA IS NOT A SEPARATOR, measured: "Bone-in, skin-on chicken thighs" carries its
 * modifiers BEFORE the comma and the product after, and truncating there turned a correct
 * row into a miss. "Peanut butter, just peanuts and salt" therefore stays a miss — cheap,
 * and the pick that ships uses the dash.
 */
const QUALIFIER = /\s[—–-]\s|[:;(]/;
function aliasNamesHead(name, entry) {
  const words = contentWords(String(name || '').split(QUALIFIER, 1)[0]);
  if (!words.length) return false;
  const last = words[words.length - 1];
  return (entry.aliases || []).some((a) => rowWords(a).includes(last));
}

/**
 * WORDS THAT QUALIFY A FOOD WITHOUT CHANGING WHAT IT IS. "organic carrots" is carrots.
 *
 * Explicit and widened deliberately, like IMPERATIVE_VERBS: an unknown modifier leaves the row
 * bare, which is the safe direction (a missed pick costs one sentence; a wrong one is a claim
 * about a different food). Never add a word that names a food or a form — oat, coconut,
 * almond, soy, goat, chocolate, powder, bread, juice, cake, chips, tortilla — those are what
 * the rule exists to stop. "fresh" is inert HERE because fresh-vs-frozen/canned is
 * stateContradicts' job, which runs first and vetoes "fresh peas" against the frozen pick.
 * Singular form (the fold runs first): "chips" would be "chip".
 *
 * "baby" and "green" were here and came out: baby corn has no husk, green garlic has no head,
 * baby broccoli is broccolini — the pick's do line described a form the shopper was not
 * holding. The colour words, "sweet" and "whole" are inert only while no pick exists for
 * potatoes, onions, rice or chicken (sweet potatoes, red onions, whole chicken are different
 * products and today resolve to cards because cards run first). WRONG_FOOD_ROWS in
 * pickReach.test.js and the probe pin that; re-check them when a pick in those families lands.
 */
export const INERT_MODIFIERS = new Set([
  'organic', 'fresh', 'ripe', 'whole', 'large', 'small', 'medium', 'big', 'bunch',
  'bag', 'head', 'loose', 'local', 'red', 'yellow', 'white', 'purple', 'sweet',
]);

/**
 * The card for a whole ROW, which is not the same question as the card for a NAME.
 *
 * AN AUTHORED `perimeterId` IS GROUND TRUTH AND OUTRANKS RETRIEVAL. A PICK names the entry
 * its judgment came from — that is what the field is for, it is claim-locked, and it was
 * chosen by a person. Retrieval is a guess about a string. Running the guess over a row
 * that already carried the answer is how "Canned skipjack tuna", authored to
 * `mercury_by_fish`, ended up telling a shopper to check the ice at a counter it will never
 * be sold from.
 *
 * Measured over the 51 shipping PICKS: 22 carry an authored id, and retrieval overrode 6 of
 * them and lost a 7th. That is a 27% error rate on the only rows where a ground truth
 * exists to check against — and the Phase 1 probe could not see any of it, because it asked
 * "did something match", never "did the RIGHT thing match".
 *
 * The authored id is still validated: an entry that has been retired, refiled as a home
    wing: /\bwings?\b/,
    whole: /\bwhole (?:chicken|turkey|bird|duck|goose)\b/,
  },
  {
    ground: /\bground\b|\bminced\b/,
    deli: /\bdeli\b|\bcold cuts\b|\blunch meat\b|\bsliced (?:turkey|chicken|ham)\b/,
    whole: /\bwhole (?:chicken|turkey|bird|duck|goose)\b/,
  },
  {
    pretzel: /\bpretzel\b/,
    sourdough: /\bsourdough\b/,
    whole_wheat: /\bwhole wheat\b/,
  },
];

const readTypes = (text, group) => new Set(
  Object.keys(group).filter((t) => group[t].test(String(text || '').toLowerCase()))
);

export function typeContradicts(name, entry) {
  if (stateContradicts(name, entry)) return true;
  // Ignore trailing label notes, just as the list's head-noun guard does.
  const subject = String(name || '').split(/\s[—–-]\s|[:;(]/, 1)[0];
  const wantStates = statesIn(subject);
  // A can is never an unspecified counter item. Even a stateless chicken/milk
  // card must explicitly cover cans before its bare food alias can retrieve it.
  if (wantStates.has('canned') && !cardStates(entry).has('canned')) return true;
  // The recommendation outranks vocabulary: breast appears in a thighs card's
  // comparison and aliases but is not what its headline/cart action recommends.
  const verdict = String(entry?.decision || '').split(/\b(?:than|instead of|rather than|not)\b|;/i, 1)[0];
  const vocabulary = [entry?.title || '', ...(entry?.aliases || [])].join(' ');
  for (const group of TYPES) {
    const want = readTypes(subject, group);
    if (!want.size) continue;
    const pick = readTypes(entry?.cart_pick, group);
    const headline = readTypes(verdict, group);
    const has = pick.size ? pick : headline.size ? headline : readTypes(vocabulary, group);
    if (![...want].some((t) => has.has(t))) return true;
  }
